import {ARENA_BOUNDS} from './view.mjs';
import {updateFinalBoss} from './encounters.mjs';
const palettes={training:['#142c26','#385d44','#b8e0aa'],industrial:['#211b18','#634531','#efb474'],mine:['#181729','#413659','#c2a4f0'],ecology:['#102923','#2f5b47','#93ddb1'],core:['#111726','#29394f','#89bedc']};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function resetWorld(r){r.worldHazards=[];r.worldClock=4;r.worldSerial=0;r.sampleRecovered=false;r.sampleNode=null;r.worldEnvironmentKills=0}
function add(r,h){r.worldHazards??=[];r.worldHazards.push({age:0,warning:1.35,life:1.3,damage:(r.quick?5:8)*(1+(r.wave-1)*.07),enemyDamage:24+r.wave*3,hitIds:[],playerHit:false,...h});r.worldHazards=r.worldHazards.slice(-12)}
function inside(h,x,y,pad=0){if(h.shape==='rect')return Math.abs(x-h.x)<h.w/2+pad&&Math.abs(y-h.y)<h.h/2+pad;if(h.shape==='crystal')return Math.abs(x-h.x)+Math.abs(y-h.y)<h.radius+pad;return Math.hypot(x-h.x,y-h.y)<h.radius+pad}
function bounds(r){return r.worldBounds||ARENA_BOUNDS}
function ambient(r){const b=bounds(r),i=r.worldSerial++,x=clamp(r.x+Math.sin(i*2.4)*160,b.left+65,b.right-65),y=clamp(r.y+Math.cos(i*1.8)*130,b.top+65,b.bottom-65);
 if(r.missionId==='industrial'){const horizontal=i%2===0;add(r,{shape:'rect',x:horizontal?(b.left+b.right)/2:x,y:horizontal?y:(b.top+b.bottom)/2,w:horizontal?b.right-b.left:58,h:horizontal?52:b.bottom-b.top,color:'#f5b27a',label:'管道泄压',life:1.15})}
 if(r.missionId==='mine')for(let n=0;n<(r.wave>=6?3:2);n++)add(r,{shape:'crystal',x:clamp(x+(n-1)*95,b.left+60,b.right-60),y:clamp(y+(n%2)*70,b.top+60,b.bottom-60),radius:44,color:'#c3a7ff',label:'晶簇开裂',warning:1.6,life:.65});
 if(r.missionId==='ecology')add(r,{shape:'pool',x,y,radius:r.wave>=6?72:58,color:'#9adba8',label:'循环迁移',warning:1.6,life:2.1});
 if(r.missionId==='core')add(r,{shape:'rect',x:clamp(x,260,1090),y,w:36,h:250,color:'#ed91b4',label:'ERROR / 校验脉冲',warning:1.4,life:.7,bossSkill:true});
}
export function updateWorld(r,dt){if(r.coreDefeated||r.state!=='playing')return;if(r.missionId!=='training'&&r.wave>=2){r.worldClock-=dt;if(r.worldClock<=0){if(r.worldHazards.length<4&&!r.enemies.some(e=>e.special&&(e.skillTimer||0)<1.8))ambient(r);r.worldClock=Math.max(5.5,9-r.wave*.3)}}
 if(r.sampleNode&&!r.sampleRecovered&&Math.hypot(r.x-r.sampleNode.x,r.y-r.sampleNode.y)<29){r.sampleRecovered=true;r.events.push('coreSample');r.burst(r.x,r.y,'#bddde0',12)}
 for(const h of r.worldHazards||[]){h.age+=dt;if(h.age<h.warning)continue;if(!h.playerHit&&inside(h,r.x,r.y,12)){h.playerHit=true;r.hurt(h.damage,{bossSkill:!!h.bossSkill});if(r.hp<=0){r.state='dead';break}}for(const e of [...r.enemies]){if(e.hp<=0||h.hitIds.includes(e.id)||!inside(h,e.x,e.y,e.r*.5))continue;h.hitIds.push(e.id);const boss=e.type===4||e.type===6,before=e.hp;r.hit(e,h.enemyDamage*(boss?.08:1),true);if(before>0&&e.hp<=0)r.worldEnvironmentKills++;if(r.state!=='playing')break}if(r.state!=='playing')break}
 r.worldHazards=(r.worldHazards||[]).filter(h=>h.age<h.warning+h.life&&(!h.sourceId||r.enemies.some(e=>e.id===h.sourceId&&e.hp>0)));if(r.hp<=0)r.state='dead';
}
export function updateMissionBoss(r,e,dt,b){if(e.missionBoss==='core'){updateFinalBoss(r,e,dt,b);return}const phase=e.hp/e.maxHp>.5?1:2;if(e.phase!==phase){e.phase=phase;e.skillTimer=1.5;r.events.push('overdrive')}e.skillTimer-=dt;if(e.skillTimer>0)return;const i=e.skillIndex||0;e.skillIndex=i+1;const common={sourceId:e.id,bossSkill:true,damage:e.damage*.75,enemyDamage:20,warning:phase===1?1.5:1.2};
 if(e.missionBoss==='industrial'){if(i%2===0){for(const offset of phase===1?[0]:[-95,95])add(r,{...common,shape:'rect',x:(b.left+b.right)/2,y:clamp(r.y+offset,b.top+65,b.bottom-65),w:b.right-b.left,h:42,color:'#f5b27a',label:'主阀排放',life:1.1})}else{add(r,{...common,shape:'rect',x:clamp(r.x,b.left+70,b.right-70),y:(b.top+b.bottom)/2,w:48,h:b.bottom-b.top,color:'#ffbc88',label:'纵向泄压',life:1.1})}}
 if(e.missionBoss==='mine'){for(let n=0;n<(phase===1?3:5);n++){const a=i*.7+n*Math.PI*2/(phase===1?3:5);add(r,{...common,shape:'crystal',x:clamp(r.x+Math.cos(a)*100,b.left+55,b.right-55),y:clamp(r.y+Math.sin(a)*100,b.top+55,b.bottom-55),radius:40,color:'#c9a8ff',label:'晶冠裂解',life:.8,warning:1.5+n*.1})}}
 if(e.missionBoss==='ecology'){for(let n=0;n<(phase===1?2:3);n++)add(r,{...common,shape:'pool',x:clamp(e.x+Math.cos(i+n*2.1)*180,b.left+90,b.right-90),y:clamp(e.y+Math.sin(i+n*2.1)*180,b.top+90,b.bottom-90),radius:phase===1?60:75,color:'#a1dfb1',label:'母体迁移',life:2,warning:1.6});if(phase===2&&r.enemies.length<65)for(const offset of [-45,45])r.spawnEnemy(3,e.x+offset,e.y+40,{hp:24,maxHp:24,child:true})}
 e.skillTimer=phase===1?4.4:3.5;r.events.push('bossZone');
}
function poly(c,x,y,r,n,rotation=0){c.beginPath();for(let i=0;i<n;i++){const a=rotation+i*Math.PI*2/n,iX=x+Math.cos(a)*r,iY=y+Math.sin(a)*r;i?c.lineTo(iX,iY):c.moveTo(iX,iY)}c.closePath()}
export function drawWorld(c,r,t){if(!r.missionId||r.missionId==='training')return;const id=r.missionId,p=palettes[id]||palettes.training;c.save();const g=c.createLinearGradient(0,0,1200,800);g.addColorStop(0,p[0]);g.addColorStop(1,p[1]);c.fillStyle=g;c.fillRect(0,0,1200,800);c.strokeStyle=p[2]+'13';c.lineWidth=1;for(let x=30;x<1200;x+=60){c.beginPath();c.moveTo(x,22);c.lineTo(x,778);c.stroke()}for(let y=20;y<800;y+=60){c.beginPath();c.moveTo(22,y);c.lineTo(1178,y);c.stroke()}c.strokeStyle=p[2]+'88';c.lineWidth=3;c.strokeRect(22,22,1156,756);
 if(id==='industrial'){for(const y of [120,680]){c.strokeStyle='#79563c';c.lineWidth=20;c.beginPath();c.moveTo(32,y);c.lineTo(1168,y);c.stroke();c.strokeStyle='#bc8b54';c.lineWidth=2;for(let x=80;x<1150;x+=100){c.strokeRect(x,y-16,14,32);c.fillStyle='#1b1a16';c.fillRect(x+30,y-8,23,16)}}for(const x of [80,1120]){c.fillStyle='#302c25';c.strokeStyle='#a77b4d';c.lineWidth=2;c.fillRect(x-25,290,50,150);c.strokeRect(x-25,290,50,150)}c.fillStyle='#e7b77866';c.font='bold 14px monospace';c.fillText('PROCESS / 04',75,755)}
 if(id==='mine'){for(let i=0;i<22;i++){const x=60+(i*173)%1080,y=90+(i*127)%640;c.save();c.translate(x,y);c.rotate(i*.9);c.fillStyle=i%3?'#48386188':'#79609a88';c.strokeStyle='#b59ad477';c.lineWidth=1;poly(c,0,0,12+i%4*5,4);c.fill();c.stroke();c.restore()}c.strokeStyle='#c5a0e333';c.lineWidth=2;for(let i=0;i<8;i++){c.beginPath();c.moveTo(50+i*143,25);c.lineTo(90+i*130,220);c.lineTo(50+i*145,500);c.stroke()}}
 if(id==='ecology'){for(let i=0;i<12;i++){const x=65+(i*197)%1070,y=100+(i*149)%610;c.fillStyle='#40775b33';c.beginPath();c.ellipse(x,y,75,34,i*.3,0,Math.PI*2);c.fill();c.strokeStyle='#96d6a922';c.lineWidth=3;c.stroke()}c.strokeStyle='#7cbd9744';c.lineWidth=8;for(const y of [110,690]){c.beginPath();c.moveTo(40,y);c.bezierCurveTo(400,y-70,800,y+70,1160,y);c.stroke()}}
 if(id==='core'){c.strokeStyle='#82a8cb44';c.lineWidth=2;for(let y=140;y<740;y+=100){c.beginPath();c.moveTo(260,y);c.lineTo(1120,y);c.stroke();for(let x=280;x<1150;x+=140){c.fillStyle=((x+y)/20)%3===0?'#a6597b':'#587d9c';poly(c,x,y,5,6,t*.05);c.fill()}}c.fillStyle='#cf96ad55';c.font='12px monospace';c.fillText('ERR / SUBJECT_NOT_RECOGNIZED',760,753)}
 if(id==='training'){c.strokeStyle='#abc99744';c.setLineDash([4,10]);c.beginPath();c.arc(600,400,180,0,Math.PI*2);c.stroke();c.setLineDash([])}
 for(const h of r.worldHazards||[]){const active=h.age>=h.warning;c.save();c.fillStyle=h.color+(active?'88':'15');c.strokeStyle=h.color;c.lineWidth=active?3:1.5;if(!active)c.setLineDash([7,7]);if(h.shape==='rect'){c.fillRect(h.x-h.w/2,h.y-h.h/2,h.w,h.h);c.strokeRect(h.x-h.w/2,h.y-h.h/2,h.w,h.h);if(active){c.globalAlpha=.5;for(let i=0;i<10;i++){const x=h.x-h.w/2+(h.w*(i/10+t*.9)%h.w);c.fillRect(x,h.y-h.h/2,3,h.h)}}}else if(h.shape==='crystal'){poly(c,h.x,h.y,h.radius,4);c.fill();c.stroke();if(active){c.beginPath();c.moveTo(h.x-h.radius,h.y);c.lineTo(h.x+h.radius,h.y);c.moveTo(h.x,h.y-h.radius);c.lineTo(h.x,h.y+h.radius);c.stroke()}}else{c.beginPath();c.ellipse(h.x,h.y,h.radius,h.radius*.9,t*.07,0,Math.PI*2);c.fill();c.stroke()}c.setLineDash([]);if(!active){c.font='10px monospace';c.textAlign='center';c.fillStyle=h.color;c.fillText(h.label,h.x,h.y-8);c.fillText(Math.max(0,h.warning-h.age).toFixed(1),h.x,h.y+8)}c.restore()}
 c.restore();
}
export function drawMissionBoss(c,e,r,t){if(!e.missionBoss)return false;const color=palettes[e.missionBoss]?.[2]||'#e8b2d3';c.save();c.translate(e.x,e.y);if(e.flash>0)c.globalAlpha=.6;c.shadowColor=color;c.shadowBlur=12;c.fillStyle='#111b25';c.strokeStyle=color;c.lineWidth=3;
 if(e.missionBossTier==='fore'){poly(c,0,0,e.r*.85,4,t*.2);c.fill();c.stroke();c.fillStyle=color;c.fillRect(-10,-6,20,12);for(let i=0;i<3;i++){c.rotate(Math.PI*2/3);c.fillRect(e.r*.8,-3,15,6)}}
 else if(e.missionBoss==='industrial'){c.fillRect(-e.r,-e.r*.8,e.r*2,e.r*1.6);c.strokeRect(-e.r,-e.r*.8,e.r*2,e.r*1.6);c.fillStyle='#b07c48';for(let side of [-1,1]){c.fillRect(side*e.r-8,-8,28,17)}c.beginPath();c.arc(0,0,e.r*.52,0,Math.PI*2);c.stroke();c.rotate(t*1.4);c.fillStyle='#f6b85b';c.fillRect(-4,-e.r*.4,8,e.r*.8)}
 else if(e.missionBoss==='mine'){poly(c,0,0,e.r,6,t*.2);c.fill();c.stroke();for(let i=0;i<6;i++){const a=t*.2+i*Math.PI/3;c.beginPath();c.moveTo(0,0);c.lineTo(Math.cos(a)*e.r,Math.sin(a)*e.r);c.stroke()}c.fillStyle='#e4c9ff';poly(c,0,0,e.r*.3,4,t);c.fill()}
 else if(e.missionBoss==='ecology'){for(let i=0;i<7;i++){const a=i*Math.PI*2/7+t*.25;c.fillStyle='#376a50';c.beginPath();c.arc(Math.cos(a)*e.r*.4,Math.sin(a)*e.r*.4,e.r*.55,0,Math.PI*2);c.fill();c.stroke()}c.fillStyle='#d1eec4';c.beginPath();c.arc(0,0,e.r*.24,0,Math.PI*2);c.fill()}
 else{poly(c,0,0,e.r,6,-t*.25);c.fill();c.stroke();c.rotate(t*.4);for(let i=0;i<3;i++){c.rotate(Math.PI*2/3);c.fillStyle=e.phase===3?'#ec809e':'#a5c5df';c.fillRect(e.r*.4,-5,e.r*.6,10)}c.rotate(-t*.4);c.fillStyle='#ffe3d9';c.fillRect(-15,-6,9,4);c.fillRect(6,-6,9,4);c.strokeStyle='#f298b1';c.beginPath();c.moveTo(-12,12);c.lineTo(0,7+Math.sin(t*7)*4);c.lineTo(12,12);c.stroke()}c.shadowBlur=0;c.restore();return true}
